import 'package:flutter/material.dart'; import '../../database/local_database.dart'; import '../../services/memories_service.dart';
class MemoriesScreen extends StatelessWidget{const MemoriesScreen({super.key});@override Widget build(BuildContext context){final f=MemoriesService(LocalDatabase()).build(DateTime.now());return Scaffold(appBar:AppBar(title:const Text('Memories')),body:FutureBuilder<List<MemoryCollection>>(future:f,builder:(c,s)=>!s.hasData?const Center(child:CircularProgressIndicator()):ListView(children:[for(final m in s.data!) ExpansionTile(title:Text(m.title),subtitle:Text('${m.items.length} items'),children:[for(final i in m.items.take(20)) ListTile(title:Text(i.fileName??i.assetId),subtitle:Text(i.createdAt.toLocal().toString()))])])));}}
